module boolean_properties (
    input wire a, b, c,
    output wire or_out,
    output wire and_out,
    output wire demorgan_lhs,
    output wire demorgan_rhs
);
    assign or_out = a | b;
    assign and_out = a & b;

    // De Morgan's Law Verification: (a & b)' == a' | b'
    assign demorgan_lhs = ~(a & b);
    assign demorgan_rhs = (~a) | (~b);
endmodule

module basic_gates (
    input wire a, b,
    output wire and_gate,
    output wire or_gate,
    output wire xor_gate,
    output wire nand_gate
);
    assign and_gate  = a & b;
    assign or_gate   = a | b;
    assign xor_gate  = a ^ b;
    assign nand_gate = ~(a & b);
endmodule

// Minimal SOP synthesized from 4-variable K-Map: F = B'D' + A'CD + AB'C
module kmap_minimized (
    input wire a, b, c, d,
    output wire f
);
    assign f = (~b & ~d) | (~a & c & d) | (a & ~b & c);
endmodule

module bcd_decoder (
    input wire [3:0] bcd,
    output reg [6:0] seg // a, b, c, d, e, f, g
);
    always @(*) begin
        case (bcd)
            4'd0: seg = 7'b1111110;
            4'd1: seg = 7'b0110000;
            // ... digits 2-9
            4'd9: seg = 7'b1111011;
            // Don't-care condition for invalid BCD inputs 10 to 15
            default: seg = 7'bxxxxxxx;
        endcase
    end
endmodule

module universal_nand (
    input wire a, b,
    output wire not_out,
    output wire and_out,
    output wire or_out
);
    // NOT via NAND
    assign not_out = ~(a & a);

    // AND via NAND-NAND
    wire nand_ab = ~(a & b);
    assign and_out = ~(nand_ab & nand_ab);

    // OR via Inverted-NAND: (a' & b')'
    wire not_a = ~(a & a);
    wire not_b = ~(b & b);
    assign or_out  = ~(not_a & not_b);
endmodule

// Majority voter: output is 1 if 2 or more of the 3 inputs are 1
module majority_voter (
    input wire a, b, c,
    output wire out
);
    assign out = (a & b) | (b & c) | (a & c);
endmodule

module full_adder (
    input wire a, b, cin,
    output wire sum, cout
);
    wire s1, c1, c2;
    // Half Adder 1
    assign s1 = a ^ b;
    assign c1 = a & b;
    // Half Adder 2 + OR
    assign sum  = s1 ^ cin;
    assign c2   = s1 & cin;
    assign cout = c1 | c2;
endmodule

module decoder_3to8 (
    input wire [2:0] in,
    input wire enable,
    output wire [7:0] out
);
    assign out = enable ? (8'b00000001 << in) : 8'b00000000;
endmodule

module mux4to1 (
    input wire [3:0] in,   // Data inputs I0, I1, I2, I3
    input wire [1:0] sel,  // Select lines S1, S0
    output wire out
);
    assign out = (sel == 2'b00) ? in[0] :
                 (sel == 2'b01) ? in[1] :
                 (sel == 2'b10) ? in[2] : in[3];
endmodule

// D Flip-Flop with asynchronous reset
module d_flip_flop (
    input wire clk, reset_n, d,
    output reg q
);
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) q <= 1'b0;
        else          q <= d;
    end
endmodule

// JK Flip-Flop
module jk_flip_flop (
    input wire clk, reset_n, j, k,
    output reg q
);
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) q <= 1'b0;
        else begin
            case ({j, k})
                2'b00: q <= q;    // Hold
                2'b01: q <= 1'b0; // Reset
                2'b10: q <= 1'b1; // Set
                2'b11: q <= ~q;   // Toggle
            endcase
        end
    end
endmodule

