#include <stdio.h>
#define LINES 4

int cache[LINES] = {-1, -1, -1, -1};

void accessMemory(int block) {
    int line = block % LINES;
    if (cache[line] == block) printf("Block %d -> Cache HIT at line %d\n", block, line);
    else {
        printf("Block %d -> Cache MISS. Placed at line %d (replaced %d)\n", block, line, cache[line]);
        cache[line] = block;
    }
}

int main() {
    accessMemory(0); accessMemory(4); accessMemory(0); // Conflict miss demonstration
    return 0;
}

#include <stdio.h>

typedef struct {
    int sourceAddr;
    int destAddr;
    int transferCount;
} DMAController;

void dmaTransfer(DMAController *dma, int *disk, int *ram) {
    printf("DMA: Transferring %d bytes directly from disk to RAM (CPU idle)...\n", dma->transferCount);
    for (int i = 0; i < dma->transferCount; i++) {
        ram[dma->destAddr + i] = disk[dma->sourceAddr + i];
    }
    printf("DMA: Transfer complete! Raising interrupt to CPU.\n");
}

int main() {
    DMAController dma = {0, 0, 4};
    int disk[] = {10, 20, 30, 40}, ram[4] = {0};
    dmaTransfer(&dma, disk, ram);
    return 0;
}
